mapper.select:
select coalesce(sum(file_size), 0)
from doc_document
where owner_id = #{ownerId}

select count(1) from doc_folder
where owner_id = #{ownerId} and parent_id = #{parentId} and deleted = '0'
  and folder_name = #{folderName}

  and folder_id != #{excludeFolderId}

select 
from doc_document d
join sys_user u on u.user_id = d.owner_id
left join doc_folder f on f.folder_id = d.folder_id and f.deleted = '0'
where d.document_id = #{documentId}
  and (d.owner_id = #{userId}
       or exists(select 1 from doc_acl access_acl
                 where access_acl.document_id = d.document_id and access_acl.user_id = #{userId}
                   and (access_acl.expires_at is null or access_acl.expires_at > now())))

select acl_id, document_id, user_id, permission, granted_by, expires_at, create_time, update_time
from doc_acl where document_id = #{documentId} and user_id = #{userId}
  and (expires_at is null or expires_at > now())

mapper.update:
update doc_acl
set permission = #{permission}, granted_by = #{grantedBy}, expires_at = #{expiresAt}, update_time = now()
where document_id = #{documentId} and user_id = #{userId}
